type Interest={id:string;sender_profile:string;target:string;message:string;status:string;created_at:number};
type State={isAdmin?:boolean;profiles:Profile[];own:Profile|null;saved:string[];sent:Interest[];received:Interest[];ownPrivate?:{name:string;birthDate:string;aadhaarLast4:string;locked:boolean;references:Reference[]};security?:{otpReady:boolean;verified:boolean;testAccess?:boolean;canPublish?:boolean;standalone?:boolean};quota?:{limit:number;used:number;day:string}};
