  async function loadChat(thread:Interest){
    setChat(thread);setChatLoading(true);setChatError('');
    try{const r=await api<{messages:ChatMessage[];hasMore:boolean}>('/api/messages?thread='+encodeURIComponent(thread.id));setChatMessages(r.messages);setChatHasMore(r.hasMore);}catch(e){setChatError((e as Error).message);}finally{setChatLoading(false);}
  }
