    try{await api('/api/actions',{method:'PATCH',body:JSON.stringify({id:chat.id,status:'ended'})});setChat(null);setChatMessages([]);setEndOpen(false);await refresh();toast.success(t('बातचीत समाप्त कर दी गई','Conversation ended'));}catch(e){toast.error((e as Error).message);}finally{setPending('');}
